    String server3Root = MerkleTreeSim.computeRootHash("User:Ali", "Order:999"); // Veri farklı!

    IO.println("Sunucu 1 ve 2 Eşit mi? " + server1Root.equals(server2Root) + " (Kök: " + server1Root + ")");
